async function findUsers(e) { $.ajax({ url: "/api/contact/user?search=" + e, type: "GET", dataType: "json", success: function (e) { 0 === e.data.length ? ($("#layout").empty(), $("#emptyState").removeClass("hidden")) : ($("#emptyState").addClass("hidden"), cardUser(e.data)) } }) } function updateStats() { $.ajax({ url: "/api/contact/user", type: "GET", dataType: "json", success: function (e) { let t = e.data || [], n = new Set(t.map((e => e.departemen))).size, a = new Set(t.map((e => e.jab))).size; $("#totalMembers").text(t.length), $("#totalDepts").text(n), $("#totalPositions").text(a) } }) } async function cardUser(e) { $.each(e, (function (e, t) { var n = `\n            <div class="bg-white rounded-lg shadow-md border border-gray-200 overflow-hidden hover:shadow-xl transition-all duration-300 hover:-translate-y-1">\n                \x3c!-- Photo Section with Click to Expand --\x3e\n                <div class="relative group overflow-hidden bg-linear-to-br from-gray-100 to-gray-200 h-48 md:h-56 cursor-pointer" onclick="openPhotoModal('${t.url}', '${t.nama}')">\n                    <img src="${t.url}" loading="lazy" class="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300" alt="${t.nama}">\n                    <div class="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all duration-300">\n                        <div class="bg-white bg-opacity-95 px-4 py-2 rounded-lg text-sm font-semibold text-gray-800 shadow-lg">\n                            <i class="fas fa-expand"></i> Lihat Penuh\n                        </div>\n                    </div>\n                </div>\n\n                \x3c!-- Content Section --\x3e\n                <div class="p-4 md:p-6">\n                    \x3c!-- Name and Department --\x3e\n                    <div class="mb-4">\n                        <h3 class="text-lg md:text-xl font-bold text-gray-900">${t.nama}</h3>\n                        <p class="text-sm text-blue-600 font-semibold mb-2">${t.jab}</p>\n                        <div class="flex items-center gap-2">\n                            <span class="inline-flex items-center px-3 py-1 rounded-full text-xs font-semibold bg-blue-100 text-blue-800">\n                                <i class="fas fa-building mr-1"></i> ${t.departemen}\n                            </span>\n                        </div>\n                    </div>\n\n                    <div class="border-t border-gray-200 pt-4">\n                        \x3c!-- Information Items --\x3e\n                        <div class="space-y-3 mb-5">\n                            \x3c!-- Jabatan Badge --\x3e\n                            <div class="flex items-center gap-3">\n                                <div class="shrink-0 w-10 h-10 bg-purple-100 rounded-lg flex items-center justify-center">\n                                    <i class="fas fa-briefcase text-purple-600"></i>\n                                </div>\n                                <div class="flex-1 min-w-0">\n                                    <p class="text-xs text-gray-500 font-medium">Posisi</p>\n                                    <p class="text-sm font-semibold text-gray-800 truncate">${t.jab}</p>\n                                </div>\n                            </div>\n\n                            \x3c!-- NIK --\x3e\n                            <div class="flex items-center gap-3">\n                                <div class="shrink-0 w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">\n                                    <i class="fas fa-id-card text-green-600"></i>\n                                </div>\n                                <div class="flex-1 min-w-0">\n                                    <p class="text-xs text-gray-500 font-medium">NIK</p>\n                                    <p class="text-sm font-semibold text-gray-800 font-mono">${t.nik}</p>\n                                </div>\n                            </div>\n\n                            \x3c!-- NoHp --\x3e\n                            <div class="flex items-center gap-3">\n                                <div class="shrink-0 w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">\n                                    <i class="fas fa-phone text-green-600"></i>\n                                </div>\n                                <div class="flex-1 min-w-0">\n                                    <p class="text-xs text-gray-500 font-medium">No WhatsApp</p>\n                                    <p class="text-sm font-semibold text-blue-600 truncate">${t.wa}</p>\n                                </div>\n                            </div>\n\n                            \x3c!-- Email --\x3e\n                            <div class="flex items-center gap-3">\n                                <div class="shrink-0 w-10 h-10 bg-orange-100 rounded-lg flex items-center justify-center">\n                                    <i class="fas fa-envelope text-orange-600"></i>\n                                </div>\n                                <div class="flex-1 min-w-0">\n                                    <p class="text-xs text-gray-500 font-medium">Email</p>\n                                    <p class="text-sm font-semibold text-blue-600 truncate">${t.email}</p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                    \x3c!-- Contact Buttons --\x3e\n                    <div class="flex gap-2 mt-6">\n                        <a href="https://wa.me/+62${t.wa.replace(/\D/g, "").replace(/^0/, "")}" target="_blank" class="flex-1 bg-linear-to-r from-green-400 to-green-500 hover:from-green-500 hover:to-green-600 text-white font-semibold py-2.5 px-3 rounded-lg transition-all duration-200 flex items-center justify-center gap-2 text-sm shadow-md hover:shadow-lg">\n                            <i class="fab fa-whatsapp"></i> <span class="hidden sm:inline">Chat</span>\n                        </a>\n                        <a href="mailto:${t.email}" class="flex-1 bg-linear-to-r from-blue-400 to-indigo-500 hover:from-blue-500 hover:to-indigo-600 text-white font-semibold py-2.5 px-3 rounded-lg transition-all duration-200 flex items-center justify-center gap-2 text-sm shadow-md hover:shadow-lg">\n                            <i class="fas fa-envelope"></i> <span class="hidden sm:inline">Email</span>\n                        </a>\n                    </div>\n                </div>\n            </div>\n        `; $("#layout").append(n) })), $(document).on("click", ".photo-modal-close", (function () { closePhotoModal() })) } function openPhotoModal(e, t) { if (0 === $("#photoModal").length) { const e = '\n            <div id="photoModal" class="fixed inset-0 bg-black bg-opacity-75 z-50 items-center justify-center p-4" style="display: none;">\n                <div class="relative max-w-2xl w-full bg-white rounded-lg overflow-hidden">\n                    \x3c!-- Close Button --\x3e\n                    <button class="photo-modal-close absolute top-4 right-4 bg-white rounded-full p-2 hover:bg-gray-200 z-10" onclick="closePhotoModal()">\n                        <i class="fas fa-times text-gray-800 text-xl"></i>\n                    </button>\n\n                    \x3c!-- Image Container --\x3e\n                    <div class="bg-black flex items-center justify-center min-h-96">\n                        <img id="modalPhotoImg" src="" alt="Photo" class="max-w-full max-h-96 object-contain">\n                    </div>\n\n                    \x3c!-- Photo Name --\x3e\n                    <div class="p-4 bg-gray-50 border-t border-gray-200">\n                        <p class="text-center text-gray-800 font-semibold" id="modalPhotoName"></p>\n                    </div>\n                </div>\n            </div>\n        '; $("body").append(e) } $("#modalPhotoImg").attr("src", e), $("#modalPhotoName").text(t), $("#photoModal").css("display", "flex") } function closePhotoModal() { $("#photoModal").css("display", "none") } $(document).ready((function () { findUsers(""), updateStats() })), $("#cariRekan").on("keyup", (function () { let e = $(this).val(); e.length % 3 != 0 && 0 !== e.length || ($("#layout").empty(), findUsers(e)) }));